            episodeNumber?: number;
            /** Format: int64 */
            libraryId?: number;
            /** Format: int64 */
            movieId?: number;
            posterPath?: string;
            /** Format: int64 */
            seasonNumber?: number;
            /** Format: int64 */
            showId?: number;
