            /** Format: int64 */
            fileId: number;
            id: string;
            /** @description Shown to admins and to the person watching. */
            ip?: string;
            item: components["schemas"]["ActivityItem"];
            /** Format: date-time */
            lastSeenAt: string;
            /** @enum {string} */
            network: "local" | "tailnet" | "remote";
            /** Format: int64 */
            pausedMs: number;
            /** Format: int64 */
            playedMs: number;
            /** Format: int64 */
            positionMs: number;
